<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Verifikasi Tanda Terima</title><style>body{font-family:Arial;background:#f1f5f3;color:#183b2b}.card{max-width:560px;margin:10vh auto;background:white;border-top:5px solid #183b2b;padding:30px;box-shadow:0 2px 12px #ccd}.valid{color:#176b45}.invalid{color:#9b2c2c}dt{color:#667}dd{font-weight:bold;margin:3px 0 15px}</style></head><body><main class="card">@if($valid)<h1 class="valid">✓ Tanda Terima Valid</h1><dl><dt>Nomor</dt><dd>{{ $snapshot['payment_number'] }}</dd><dt>Nama</dt><dd>{{ str(data_get($snapshot,'student.name'))->before(' ').' '.str(str(data_get($snapshot,'student.name'))->after(' '))->substr(0,1).'.' }}</dd><dt>Tanggal</dt><dd>{{ \Carbon\Carbon::parse($snapshot['paid_at'])->locale('id')->translatedFormat('d F Y') }}</dd><dt>Periode</dt><dd>{{ data_get($snapshot,'invoice.period') }}</dd><dt>Pembayaran</dt><dd>Rp {{ number_format($snapshot['amount'],0,',','.') }}</dd><dt>Status</dt><dd>{{ $snapshot['status'] }}</dd></dl>@else<h1 class="invalid">Tanda terima tidak ditemukan atau tidak valid.</h1><p>Periksa kembali kode verifikasi pada dokumen resmi.</p>@endif</main></body></html>
